import{_ as e,o,c as i,a6 as t}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Downloads e atualizações","description":"","frontmatter":{"title":"Downloads e atualizações","docId":"user.start.updates","translationKey":"user.start.updates","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"e9a16659dc888de9dc4a736ce6c66d6a0d55643d950c336d4c479849f3196d54","order":40},"headers":[],"relativePath":"pt/user/updates.md","filePath":"pt/user/updates.md","lastUpdated":1794611623000}'),s={name:"pt/user/updates.md"};function r(d,a,l,n,c,u){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="downloads-and-updates" tabindex="-1">Downloads e atualizações <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to &quot;Downloads e atualizações {#downloads-and-updates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Escolha o canal de versão correto e atualize sem confundir uma verificação de atualização com instalação automática. Feche sessões ativas e faça backup dos dados locais antes de mudar de versão, especialmente quando houver uma migração de banco de dados documentada.</p><h2 id="select-a-channel" tabindex="-1">Selecione um canal <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to &quot;Selecione um canal {#select-a-channel}&quot;">​</a></h2><p>A <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versões</a> identifica versões estáveis e preliminares. Uma candidata como <code>-rc</code> se destina à verificação. O atualizador do aplicativo distingue feeds estável e beta; ele autentica metadados assinados antes de oferecer uma versão. Um arquivo JSON sem assinatura ou um instalador alterado não é uma atualização aceita.</p><h2 id="check-and-install" tabindex="-1">Verifique e instale <a class="header-anchor" href="#check-and-install" aria-label="Permalink to &quot;Verifique e instale {#check-and-install}&quot;">​</a></h2><ol><li>Abra <strong>Settings → General</strong> e inspecione o estado atual do atualizador e a versão instalada.</li><li>Execute a verificação disponível. Compilações sem a chave pública ou capacidade de feed configurada mostram que as verificações estão indisponíveis.</li><li>Leia as notas de versão e escolha o pacote para sua plataforma.</li><li>Quando a compilação oferecer download ou encaminhamento manual, siga esse caminho. O fluxo habilita verificações autenticadas somente com a variável de chave pública configurada; a instalação automática tem portas adicionais.</li><li>Para uma atualização manual, feche o TikTools, substitua ou instale o pacote verificado completo e reabra. Mantenha o diretório de dados separado dos arquivos do aplicativo.</li></ol><h2 id="expected-result" tabindex="-1">Resultado esperado <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Resultado esperado {#expected-result}&quot;">​</a></h2><p>O aplicativo reiniciado informa a versão escolhida e consegue ler o perfil local esperado. Pacotes portáteis ZIP/TAR exigem substituição manual. Instalações com disposição desconhecida ou extraída também podem exigir um caminho manual mesmo quando existe um instalador AppImage.</p><h2 id="recovery-and-limitations" tabindex="-1">Recuperação e limitações <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to &quot;Recuperação e limitações {#recovery-and-limitations}&quot;">​</a></h2><p>Uma falha na verificação de assinatura significa falha na atualização; baixe uma cópia oficial nova e verifique as somas de verificação da versão. Não contorne a verificação. A substituição automática de AppImage e o encaminhamento para NSIS têm controles de compilação separados e são experimentais. Não existe reversão automática geral. Voltar a um binário antigo não desfaz um esquema SQLite migrado.</p><p>Informe a versão instalada, o formato do pacote e o erro do atualizador em Diagnostics. Não anexe chaves de assinatura, tokens de convite ou dados da conta. O <a href="./installation.html">guia de instalação</a> descreve as disposições de pacote compatíveis.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>A capacidade do updater é fixada na compilação. Verificar exige feed e chave pública. AppImage automático exige também porta comum de instalação e origem suportada detectada; NSIS exige essa mesma porta E a específica NSIS. Variáveis após instalar não ativam portas compiladas. Portable/extraído/desconhecido usa substituição manual. Verifique versão, reinício e perfil após instalar; download, checksum ou abrir instalador não comprovam conclusão.</p>',14)])])}const h=e(s,[["render",r]]);export{m as __pageData,h as default};
